        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    totalScore: 0,
                    aiQualityScore: 0,
                    decisionQualityScore: 0,
                    ethicsScore: 0,
                    totalScoreHistory: [],
                    aiScoreHistory: [],
                    decisionScoreHistory: [],
                    roundScores: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    promptLevel: 3,
                    caughtFlaw: 0,
                    businessDecision: 1,
                    ethicsChoice: 2
                };
            }
            this._updateBriefing(state);
            if (!this._langBound) {
                this._langBound = true;
                var selfL = this;
                var repaint = function() { try { if (window.mySimulation && window.mySimulation.state) selfL._updateBriefing(window.mySimulation.state); } catch (e) {} };
                document.addEventListener('express:langchanged', function() { setTimeout(repaint, 0); });
                try { if (window.mySimulation && window.mySimulation.eventBus) window.mySimulation.eventBus.on('language:changed', function() { setTimeout(repaint, 0); }); } catch (e) {}
            }
        }

        validateDecisions(decisions) {
            var promptInput = document.getElementById('promptLevelInput');
            if (promptInput) decisions.promptLevel = parseInt(promptInput.value);

            var flawInput = document.getElementById('caughtFlawInput');
            if (flawInput) decisions.caughtFlaw = parseInt(flawInput.value);

            var decInput = document.getElementById('businessDecisionInput');
            if (decInput) decisions.businessDecision = parseInt(decInput.value);

            var ethicsInput = document.getElementById('ethicsInput');
            if (ethicsInput) decisions.ethicsChoice = parseInt(ethicsInput.value);

            if (!decisions.promptLevel || decisions.promptLevel < 1 || decisions.promptLevel > 5) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('prompt_warning'), 'warning'
                );
                return false;
            }

            if (isNaN(decisions.caughtFlaw) || decisions.caughtFlaw < 0 || decisions.caughtFlaw > 3) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('flaw_warning'), 'warning'
                );
                return false;
            }

            if (!decisions.businessDecision || decisions.businessDecision < 1 || decisions.businessDecision > 4) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('decision_warning'), 'warning'
                );
                return false;
            }

            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var roundIdx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[roundIdx];

            // flaw credit only when the student names the real flaw of this round (no self-attestation)
            var flawRight = d.caughtFlaw === round.flawCorrect;
            // a richer prompt pays only when its output is checked: a polished unchecked answer is more persuasive, not more useful
            var PROMPT_CHECKED = [5, 10, 15, 20, 25];
            var PROMPT_UNCHECKED = [5, 8, 9, 8, 6];
            var lvl = Math.max(1, Math.min(5, d.promptLevel || 1));
            var promptScore = (flawRight ? PROMPT_CHECKED : PROMPT_UNCHECKED)[lvl - 1];
            var flawScore = flawRight ? 15 : 0;
            var aiScore = promptScore + flawScore;

            var decIdx = d.businessDecision - 1;
            var decisionScore = round.decisionScores[decIdx] || 0;

            var integrationBonus = 0;
            if (d.promptLevel >= 3 && flawRight && decisionScore >= 35) {
                integrationBonus = 10;
            } else if (d.promptLevel >= 2 && decisionScore >= 25) {
                integrationBonus = 5;
            }

            var ethicsPoints = 0;
            if (round.hasEthics) {
                if (roundIdx === 2) {
                    if (d.ethicsChoice === 1) ethicsPoints = -5;
                    else if (d.ethicsChoice === 2) ethicsPoints = 3;
                    else if (d.ethicsChoice === 3) ethicsPoints = 5;
                } else if (roundIdx === 4) {
                    if (d.ethicsChoice === 1) ethicsPoints = 5;
                    else if (d.ethicsChoice === 2) ethicsPoints = 3;
                    else if (d.ethicsChoice === 3) ethicsPoints = -5;
                }
            }

            var c = this._consequences(state.domainState, roundIdx + 1, d, flawRight);
            var roundTotal = Math.max(0, Math.round((aiScore * 0.40) + (decisionScore * 0.60) + integrationBonus + ethicsPoints) + c.pts);
            var weightedScore = Math.round(roundTotal * round.roundWeight * 100) / 100;

            state.domainState.totalScore += weightedScore;
            state.domainState.aiQualityScore += Math.round(aiScore * round.roundWeight * 100) / 100;
            state.domainState.decisionQualityScore += Math.round(decisionScore * round.roundWeight * 100) / 100;
            state.domainState.ethicsScore += ethicsPoints;

            state.domainState.totalScoreHistory.push(Math.round(state.domainState.totalScore * 10) / 10);
            state.domainState.aiScoreHistory.push(aiScore);
            state.domainState.decisionScoreHistory.push(decisionScore);
            state.domainState.roundScores.push(roundTotal);

            // platform score: points earned so far over the best points available so far (56 per round, 61 in the ethics rounds)
            var overallScore = this._composite(state.domainState.roundScores);
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: overallScore });

            var self = this;
            var nextPeriod = (state.currentPeriod || 1) + 1;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: nextPeriod });
            }, 500);

            return {
                period: state.currentPeriod,
                roundName: this._tr(round.titleKey, round.title),
                promptScore: promptScore,
                flawScore: flawScore,
                flawPick: d.caughtFlaw,
                flawRight: flawRight,
                aiScore: aiScore,
                decisionScore: decisionScore,
                integrationBonus: integrationBonus,
                ethicsPoints: ethicsPoints,
                consequencePts: c.pts,
                events: c.events,
                mistakes: c.made,
                roundIdx: roundIdx,
                roundTotal: roundTotal,
                weightedScore: weightedScore,
                totalScore: Math.round(state.domainState.totalScore * 10) / 10
            };
        }

        // Effects of a decision that land in later rounds (EQIL S3). Sources: TN 5.2 to 5.4, Q2, Q3, Exhibit 5; case, Industry context.
        // Pending effects live in domainState, so undo and resume replay them exactly.
        _consequences(ds, period, d, flawRight) {
            if (!Array.isArray(ds.pending)) ds.pending = [];
            if (!Array.isArray(ds.mistakes)) ds.mistakes = [];
            var landed = ds.pending.filter(function(p) { return p.round === period; });
            ds.pending = ds.pending.filter(function(p) { return p.round !== period; });
            var pts = landed.reduce(function(sum, p) { return sum + p.pts; }, 0);
            var events = landed.map(function(p) { return p.key; });
            var made = [];
            if (period === 2 && d.businessDecision === 1) {
                made.push('m_invima');
                ds.pending.push({ round: 3, pts: -16, key: 'evt_invima_r3' }, { round: 4, pts: -16, key: 'evt_invima_r4' });
            }
            if (period === 3 && d.ethicsChoice === 1) {
                made.push('m_privacy');
                ds.pending.push({ round: 4, pts: -11, key: 'evt_privacy_r4' }, { round: 5, pts: -11, key: 'evt_privacy_r5' });
            }
            if (period === 3 && d.businessDecision === 4) {
                made.push('m_territory');
                ds.pending.push({ round: 4, pts: -6, key: 'evt_territory_r4' });
            }
            if (period === 4 && d.businessDecision === 3) {
                made.push('m_pricing');
                ds.pending.push({ round: 5, pts: -8, key: 'evt_pricing_r5' });
            }
            if (period === 5) {
                var presented = d.businessDecision === 3 || (d.businessDecision === 1 && (d.ethicsChoice === 3 || !flawRight));
                if (presented) {
                    pts += -22;
                    events.push('evt_cfo');
                    made.push(d.businessDecision === 3 ? 'm_asis' : (d.ethicsChoice === 3 ? 'm_selfaudit' : 'm_unflagged'));
                }
            }
            ds.mistakes = ds.mistakes.concat(made);
            return { pts: pts, events: events, made: made };
        }

        // One function for score, tier id and label (G-D). Thresholds from the sweep: TN play 100, its defensible R1 variant 97, each TN mistake 89 or less, random median under 50.
        _composite(totals) {
            var self = this, got = 0, best = 0;
            (totals || []).forEach(function(v, i) { var r = self.ROUNDS[Math.min(i, self.ROUNDS.length - 1)]; got += v || 0; best += r.hasEthics ? 61 : 56; });
            return best ? Math.max(0, Math.min(100, Math.round(100 * got / best))) : 0;
        }

        _tierOf(score) {
            if (score >= 92) return 'expert';
            if (score >= 75) return 'proficient';
            if (score >= 50) return 'developing';
            return 'beginning';
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('totalScoreDisplay', 'domainState.totalScore',
                function(v) { return Math.round(v * 10) / 10; });
            uiManager.bind('aiScoreDisplay', 'domainState.aiQualityScore',
                function(v) { return Math.round(v * 10) / 10; });
            uiManager.bind('decisionScoreDisplay', 'domainState.decisionQualityScore',
                function(v) { return Math.round(v * 10) / 10; });
            uiManager.bind('ethicsScoreDisplay', 'domainState.ethicsScore');
        }

        getChartConfig() {
            return {
                scoreChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: this._tr('chart_ai_quality', 'AI Quality'),
                                data: [],
                                backgroundColor: 'rgba(155,89,182,0.7)',
                                borderColor: '#9b59b6',
                                borderWidth: 2
                            },
                            {
                                label: this._tr('chart_decision_quality', 'Decision Quality'),
                                data: [],
                                backgroundColor: 'rgba(39,174,96,0.7)',
