                                borderWidth: 2
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: this._tr('chart_title_perf', 'Performance by Round') }
                        },
                        scales: {
                            y: { beginAtZero: true, max: 60, title: { display: true, text: this._tr('chart_axis_score', 'Score') } }
                        }
                    }
