        getChartData(state) {
            var labels = state.domainState.aiScoreHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                scoreChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.aiScoreHistory },
                        { data: state.domainState.decisionScoreHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var totals = history.map(function(r) { return r.results ? r.results.roundTotal || 0 : 0; });
            var totalScore = totals.reduce(function(s, v) { return s + v; }, 0);
            var avgScore = totalScore / totals.length;
            var aiScores = history.map(function(r) { return r.results ? r.results.aiScore || 0 : 0; });
            var avgAI = aiScores.reduce(function(s, v) { return s + v; }, 0) / aiScores.length;
            var flawsCaught = history.filter(function(r) { return r.results && r.results.flawScore > 0; }).length;
            var flawsCaughtCount = flawsCaught;

            var overall = this._composite(totals);
            var self = this;
            var rounds = history.map(function(h, i) {
                var r = h.results || {};
                var ri = typeof r.roundIdx === 'number' ? r.roundIdx : i;
                var spec = self.ROUNDS[Math.min(ri, self.ROUNDS.length - 1)];
                return {
                    n: ri + 1, total: r.roundTotal || 0, max: spec.hasEthics ? 61 : 56,
                    dec: r.decisionScore || 0, ai: r.aiScore || 0, flawRight: !!r.flawRight,
                    lvl: h.decisions ? (h.decisions.promptLevel || 0) : 0,
                    made: Array.isArray(r.mistakes) ? r.mistakes : [], events: Array.isArray(r.events) ? r.events : [],
                    cons: r.consequencePts || 0
                };
            });
            var tier = this._tierOf(overall);
            var performance = this._tr('perf_' + tier, tier);

            var insights = [];
            if (avgAI < 20) insights.push(this._tr('insight_low_ai', 'Focus on improving prompt sophistication — use role assignment and structured output formats.'));
            if (flawsCaught < 3) insights.push(this._tr('insight_low_flaws', 'Practice identifying AI hallucinations: check citations, question suspiciously precise numbers, and verify geographic assumptions.'));
            if (avgScore > 50) insights.push(this._tr('insight_strong_integration', 'Strong integration of AI analysis with independent judgment.'));
            if (flawsCaught >= 4) insights.push(this._tr('insight_excellent_eval', 'Excellent critical evaluation of AI outputs — you caught most embedded flaws.'));

            return {
                totalScore: overall,
                sumRoundTotals: totalScore,
                rounds: rounds,
                avgScore: Math.round(avgScore),
                avgAIScore: Math.round(avgAI),
                flawsCaught: this._tr('flaws_caught_of', '{n} of 5').split('{n}').join(flawsCaught),
                flawsCaughtCount: flawsCaughtCount,
                performance: tier,
                performanceKey: 'perf_' + tier,
                performanceLabel: performance,
                overallScore: overall,
                score: overall,
                insights: insights
            };
        }

        _fill(key, fb, vals) {
            var txt = this._tr(key, fb);
            Object.keys(vals || {}).forEach(function(k) { txt = txt.split('{' + k + '}').join(String(vals[k])); });
            return txt;
        }

        _insights(sum) {
            var self = this, out = [], rounds = sum.rounds || [];
            var made = [];
            rounds.forEach(function(r) { r.made.forEach(function(m) { if (made.indexOf(m) < 0) made.push(m); }); });
            made.slice(0, 3).forEach(function(m) { out.push(self._tr(m, m)); });
            var missed = rounds.filter(function(r) { return !r.flawRight; }).map(function(r) { return r.n; });
            if (missed.length) out.push(this._fill('ins_flaws_missed', 'You let the AI error through in these rounds: {list}.', { list: missed.join(', ') }));
            else out.push(this._tr('ins_flaws_all', 'You named the real AI problem in all five rounds.'));
            var strong = rounds.filter(function(r) { return r.dec >= 45; }).length;
            out.push(this._fill('ins_decisions', 'Your strategic decision was among the strongest options in {n} of 5 rounds.', { n: strong }));
            if (out.length < 5 && rounds.some(function(r) { return !r.flawRight && r.lvl >= 4; })) out.push(this._tr('ins_prompt_unchecked', 'A polished answer you did not check is more persuasive, not more useful.'));
            if (out.length < 5 && !made.length) out.push(this._tr('ins_clean', 'No decision of yours came back to cost you in a later round.'));
            return out.slice(0, 5);
        }

        formatCompletionMessage(summary) {
            var self = this, sum = summary || {}, rounds = sum.rounds || [];
            var esc = function(v) { return String(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); };
            var n = rounds.length || 1;
            var decPct = Math.round(100 * rounds.reduce(function(a, r) { return a + r.dec; }, 0) / (50 * n));
            var aiPct = Math.round(100 * rounds.reduce(function(a, r) { return a + r.ai; }, 0) / (40 * n));
            var cons = rounds.reduce(function(a, r) { return a + r.cons; }, 0);
            var flaws = rounds.filter(function(r) { return r.flawRight; }).length;
            var worst = null;
            rounds.forEach(function(r) { var lost = r.max - r.total; if (!worst || lost > worst.lost) worst = { r: r, lost: lost }; });
            var turn = '';
            if (worst && worst.lost > 9) {
                turn = this._fill('cm_turn_text', 'Round {n} cost you the most.', { n: worst.r.n, lost: worst.lost });
                if (worst.r.made.length) turn += ' ' + this._tr('cm_turn_made', '');
                else if (worst.r.events.length) turn += ' ' + this._tr('cm_turn_event', '');
            } else {
                turn = this._fill('cm_turn_clean', 'No round broke the run.', { lost: worst ? worst.lost : 0 });
            }
            var kpi = function(label, value) { return '<div class="genai-cm-kpi"><div class="genai-cm-kpi-label">' + esc(label) + '</div><div class="genai-cm-kpi-value">' + esc(value) + '</div></div>'; };
            var h = '<div class="genai-cm">';
            h += '<h3 class="genai-cm-title">' + esc(this._tr('cm_title', 'Debrief')) + '</h3>';
            h += '<div class="genai-cm-score"><span class="genai-cm-score-num">' + esc(sum.overallScore != null ? sum.overallScore : 0) + '/100</span> <span class="genai-cm-verdict genai-cm-tier-' + esc(sum.performance || 'beginning') + '">' + esc(sum.performanceLabel || '') + '</span></div>';
            h += '<div class="genai-cm-kpis">' + kpi(this._tr('cm_outcome', 'Outcome'), decPct + '/100') + kpi(this._tr('cm_process', 'Process'), aiPct + '/100') +
                kpi(this._tr('cm_kpi_flaws', 'AI problems named'), flaws + '/5') + kpi(this._tr('cm_kpi_conseq', 'Points lost to consequences'), String(cons)) + '</div>';
            h += '<h4>' + esc(this._tr('cm_turning', 'Turning point')) + '</h4><p>' + esc(turn) + '</p>';
            h += '<h4>' + esc(this._tr('cm_insights', 'What happened in your run')) + '</h4><ul>';
            this._insights(sum).forEach(function(t) { h += '<li>' + esc(t) + '</li>'; });
            h += '</ul><h4>' + esc(this._tr('cm_questions', 'For class discussion')) + '</h4><ol>';
            ['cm_q1', 'cm_q2', 'cm_q3'].forEach(function(k) { h += '<li>' + esc(self._tr(k, '')) + '</li>'; });
            h += '</ol></div>';
            return h;
        }

        // Review of the round just played, kept on screen until the next submit (F6, L9)
        _renderReview(p) {
            var box = document.getElementById('roundReviewBox');
            if (!box) return;
            var sim = window.mySimulation, hist = sim && sim.state && Array.isArray(sim.state.history) ? sim.state.history : [];
            var last = hist.length ? hist[hist.length - 1] : null;
            var r = last && last.results ? last.results : null;
            if (!r || typeof r.roundIdx !== 'number' || r.roundIdx + 2 !== p) { box.hidden = true; box.innerHTML = ''; return; }
            var n = r.roundIdx + 1, spec = this.ROUNDS[r.roundIdx], self = this;
            var verdict = r.flawRight ? 'rev_flaw_right' : (r.flawPick === 0 ? 'rev_flaw_none' : 'rev_flaw_wrong');
            var h = '<h4>' + this._fill('rev_title', 'Review of round {n}', { n: n }) + '</h4>';
            h += '<p><b>' + this._tr(verdict, '') + '</b> ' + this._tr('rev_what', 'What the AI got wrong:') + ' ' + this._tr('round' + n + '_flawdesc', spec.flawDescription) + '</p>';
            (r.events || []).forEach(function(e) { h += '<p class="genai-sim-event"><b>' + self._tr('evt_heading', '') + ':</b> ' + self._tr(e, e) + '</p>'; });
            h += '<p>' + this._fill('rev_pts', 'Round score {t}', { t: r.roundTotal, d: r.decisionScore, a: r.aiScore, c: r.consequencePts || 0 }) + '</p>';
            box.innerHTML = h;
            box.hidden = false;
        }

        getHint(state, results) {
            if (results.flawScore === 0) return window.mySimulation.t('hint_missed_flaw');
            if (results.promptScore <= 10) return window.mySimulation.t('hint_low_prompt');
            if (results.decisionScore >= 45) return window.mySimulation.t('hint_great_decision');
            if (results.roundTotal >= 50) return window.mySimulation.t('hint_good_round');
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.roundName', label: 'Round', i18nKey: 'col_round' },
                { key: 'results.promptScore', label: 'Prompt', i18nKey: 'col_prompt', formatter: function(v) { return v + '/25'; } },
                { key: 'results.flawScore', label: 'Flaw Detection', i18nKey: 'col_flaw', formatter: function(v) { return v > 0 ? window.mySimulation.t('flaw_caught') : window.mySimulation.t('flaw_missed'); } },
