        _tr(key, fallback) {
            var sim = window.mySimulation;
            var v = sim && sim.t ? sim.t(key) : null;
            return (v && v !== key) ? v : fallback;
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var n = idx + 1;

            var titleEl = document.getElementById('roundTitle');
            if (titleEl) titleEl.innerHTML = this._tr(round.titleKey, round.title);

            var briefEl = document.getElementById('briefingText');
            var simState = window.mySimulation && window.mySimulation.state ? window.mySimulation.state : null;
            var pend = simState && simState.domainState && Array.isArray(simState.domainState.pending) ? simState.domainState.pending : [];
            var notes = '';
            var selfB = this;
            pend.filter(function(pe) { return pe.round === n && (state.currentPeriod || 1) === n; }).forEach(function(pe) {
                notes += '<p class="genai-sim-event"><b>' + selfB._tr('evt_heading', '') + ':</b> ' + selfB._tr(pe.key, pe.key) + '</p>';
            });
            if (briefEl) briefEl.innerHTML = notes + this._tr('round' + n + '_desc', round.description);
            this._renderReview(state.currentPeriod || 1);

            var aiEl = document.getElementById('aiOutputText');
            if (aiEl) aiEl.innerHTML = this._tr('round' + n + '_ai', round.aiOutput);

            var ethicsPanel = document.getElementById('ethicsPanel');
            if (ethicsPanel) {
                ethicsPanel.style.display = round.hasEthics ? 'block' : 'none';
            }

            if (round.hasEthics && round.ethicsOptions.length > 0) {
                for (var e = 0; e < round.ethicsOptions.length; e++) {
                    var optEl = document.getElementById('ethicsOpt' + (e + 1));
                    if (optEl) optEl.textContent = this._tr('round' + n + '_ethics' + (e + 1), round.ethicsOptions[e]);
                }
            }

            for (var i = 0; i < round.options.length; i++) {
                var decEl = document.getElementById('decOpt' + (i + 1));
                if (decEl) decEl.textContent = this._tr('round' + n + '_opt' + (i + 1), round.options[i]);
            }

            var chartEl = document.getElementById('scoreChart');
            if (chartEl) chartEl.setAttribute('aria-label', this._tr('chart_alt', 'Bar chart: AI use quality and decision quality by round. The same figures are in the history table above.'));
            var noneEl = document.getElementById('flawOpt0');
            if (noneEl) noneEl.textContent = this._tr('flaw_none', 'No material issue: the output can be used for this decision as it stands');
            for (var f = 0; f < round.flawOptions.length; f++) {
                var fEl = document.getElementById('flawOpt' + (f + 1));
                if (fEl) fEl.textContent = this._tr('round' + n + '_flaw' + (f + 1), round.flawOptions[f]);
            }

            var hintBox = document.getElementById('flawHintBox');
            if (hintBox) hintBox.style.display = 'none';
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new GenAIManagementAdapter(), {
            simulationType: 'genai_management_tool',
            maxPeriods: 5,
            autoSaveInterval: 30000
        });
    });

})();
